import sys
from math import gcd
from fractions import Fraction
def main():
    d = sys.stdin.buffer.read().split()
    n, k = int(d[0]), int(d[1])
    x = list(map(int, d[2:2 + n]))
    g = [b - a for a, b in zip(x, x[1:])]
    # D* = (k+1)-th largest value in the union of {g/m : m >= 1}
    need = k + 1
    lo, hi = 0.0, float(max(g)) * 1.0000001
    for _ in range(110):
        m = (lo + hi) / 2
        if sum(int(v / m) for v in g) >= need:
            lo = m
        else:
            hi = m
    cand = set()
    for v in g:
        b = int(v / lo) if lo > 0 else 1
        for mm in range(b - 2, b + 3):
            if mm >= 1:
                cand.add(Fraction(v, mm))
    cand = sorted(cand)
    def cnt(fr):
        p, q = fr.numerator, fr.denominator
        return sum(v * q // p for v in g)
    l, r = 0, len(cand) - 1
    while l < r:  # largest candidate with cnt >= need
        mid = (l + r + 1) // 2
        if cnt(cand[mid]) >= need:
            l = mid
        else:
            r = mid - 1
    a = cand[l]
    print(f"{a.numerator}/{a.denominator}")
main()

import sys, heapq
def main():
    d = sys.stdin.buffer.read().split()
    n = int(d[0])
    ev = []
    for i in range(n):
        l, r, h = int(d[1 + 3 * i]), int(d[2 + 3 * i]), int(d[3 + 3 * i])
        ev.append((l, -h, r))
        ev.append((r, 0, 0))
    ev.sort()
    heap = [(0, float("inf"))]
    pts = []
    for x, nh, r in ev:
        while heap[0][1] <= x:
            heapq.heappop(heap)
        if nh:
            heapq.heappush(heap, (nh, r))
        h = -heap[0][0]
        if not pts or pts[-1][1] != h:
            if pts and pts[-1][0] == x:
                pts[-1] = (x, h)
                if len(pts) > 1 and pts[-2][1] == h:
                    pts.pop()
            else:
                pts.append((x, h))
    area = 0
    for (x1, h1), (x2, _) in zip(pts, pts[1:]):
        area += (x2 - x1) * h1
    c = 0
    for i, (x, h) in enumerate(pts, 1):
        c += i * x + h
    print(len(pts))
    print(area)
    print(c % 1000000007)
main()

import sys
def main():
    d = sys.stdin.read().split()
    n, k = int(d[0]), int(d[1])
    a = list(map(int, d[2:2 + n]))
    full = (1 << n) - 1
    ss = [0] * (1 << n)
    for m in range(1, 1 << n):
        low = m & -m
        ss[m] = ss[m ^ low] + a[low.bit_length() - 1]
    mx = max(a)
    cands = sorted(set(v for v in ss if v >= mx))
    BIG = 1 << 40
    bits = [(1 << i, a[i]) for i in range(n)]
    def ok(T):
        dp = [0] * (1 << n)
        dp[0] = BIG  # one open worker, load 0
        for m in range(1, 1 << n):
            best = None
            for b, w in bits:
                if m & b:
                    p = dp[m ^ b]
                    if (p & (BIG - 1)) + w <= T:
                        v = p + w
                    else:
                        v = ((p >> 40) + 1 << 40) + w
                    if best is None or v < best:
                        best = v
            dp[m] = best
        return dp[full] >> 40 <= k
    lo, hi = 0, len(cands) - 1
    while lo < hi:
        mid = (lo + hi) // 2
        if ok(cands[mid]):
            hi = mid
        else:
            lo = mid + 1
    print(cands[lo])
main()
